refentry.refsect1:
&reftitle.description;
public boolnullYaf_Controller_Abstract::setViewpath stringview_directory
Define o diretório de modelos do mecanismo de visualização associado a este controlador.

&reftitle.parameters;


  view_directory


    O diretório que contém os modelos de visualização.

  &reftitle.examples;

   Exemplo de Yaf_Controller_Abstract::setViewpath


<?php
class ProductController extends Yaf_Controller_Abstract
{
    public function init() {
        // a partir de agora os modelos deste controlador são procurados
        // em application/themes/dark/views/
        $this->setViewpath(APPLICATION_PATH . "/themes/dark/views");
    }

    public function indexAction() {
        // renderiza application/themes/dark/views/product/index.phtml
        $this->display("product/index.phtml");
    }
}
?>
